"""Scoped bank read API routes under ``/internal/bank/...``.

All endpoints require ``bank:read`` scope and filter to ``principal.user_id``.
Another user's resource IDs return 404 (not 403) to avoid existence leaks.
"""

from __future__ import annotations

from fastapi import APIRouter, Depends, HTTPException, Query, status

from gateway.auth.delegation import Principal, require_principal
from gateway.bank import MAX_LIST_SIZE, MAX_QUERY_LENGTH, BankStore
from gateway.bank_models import (
    AccountResponse,
    BillerResponse,
    CardResponse,
    HoldingResponse,
    PayeeResponse,
    QuoteIssueRequest,
    QuoteResponse,
    TransactionResponse,
)

router = APIRouter(prefix="/internal/bank", tags=["bank-read"])

# Module-level store instance; initialized lazily.
_store: BankStore | None = None


def get_bank_store() -> BankStore:
    global _store  # noqa: PLW0603
    if _store is None:
        from shared.settings import load_gateway_settings

        _store = BankStore(load_gateway_settings().db_path)
    return _store


def _set_bank_store(store: BankStore) -> None:
    """Test override: inject a store with a temp DB path."""
    global _store  # noqa: PLW0603
    _store = store


# ── Accounts ────────────────────────────────────────────────────────


@router.get("/accounts", response_model=list[AccountResponse])
async def list_accounts(
    principal: Principal = Depends(require_principal("bank:read")),
) -> list[dict]:
    store = get_bank_store()
    return store.get_accounts(principal.user_id)


@router.get("/accounts/{account_id}", response_model=AccountResponse)
async def get_account(
    account_id: str,
    principal: Principal = Depends(require_principal("bank:read")),
) -> dict:
    store = get_bank_store()
    account = store.get_account(principal.user_id, account_id)
    if account is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="account not found")
    return account


# ── Payees ──────────────────────────────────────────────────────────


@router.get("/payees/search", response_model=list[PayeeResponse])
async def search_payees(
    principal: Principal = Depends(require_principal("bank:read")),
    q: str = Query(..., min_length=1, max_length=MAX_QUERY_LENGTH),
) -> list[dict]:
    store = get_bank_store()
    return store.search_payees(principal.user_id, q)


# ── Billers ─────────────────────────────────────────────────────────


@router.get("/billers", response_model=list[BillerResponse])
async def list_billers(
    principal: Principal = Depends(require_principal("bank:read")),
) -> list[dict]:
    store = get_bank_store()
    return store.get_billers(principal.user_id)


# ── Cards ──────────────────────────────────────────────────────────


@router.get("/cards", response_model=list[CardResponse])
async def list_cards(
    principal: Principal = Depends(require_principal("bank:read")),
) -> list[dict]:
    store = get_bank_store()
    return store.get_cards(principal.user_id)


@router.get("/cards/{card_id}", response_model=CardResponse)
async def get_card(
    card_id: str,
    principal: Principal = Depends(require_principal("bank:read")),
) -> dict:
    store = get_bank_store()
    card = store.get_card(principal.user_id, card_id)
    if card is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="card not found")
    return card


# ── Holdings ────────────────────────────────────────────────────────


@router.get("/holdings", response_model=list[HoldingResponse])
async def list_holdings(
    principal: Principal = Depends(require_principal("bank:read")),
) -> list[dict]:
    store = get_bank_store()
    return store.get_holdings(principal.user_id)


# ── Quotes ──────────────────────────────────────────────────────────


@router.post("/quotes", response_model=QuoteResponse)
async def issue_quote(
    body: QuoteIssueRequest,
    principal: Principal = Depends(require_principal("bank:read")),
) -> dict:
    """Issue a new mock equity quote.  POST is the only write-ish endpoint:
    it creates a new quote row.  Quotes are never mutated; expired quotes
    stay expired."""
    store = get_bank_store()
    try:
        return store.get_quote(body.symbol)
    except ValueError as exc:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail=str(exc),
        ) from None


@router.get("/quotes/{quote_id}", response_model=QuoteResponse)
async def get_quote(
    quote_id: str,
    principal: Principal = Depends(require_principal("bank:read")),
) -> dict:
    store = get_bank_store()
    quote = store.fetch_quote(quote_id)
    if quote is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="quote not found")
    # Report expired quotes but still return the data.
    return quote


@router.get("/quotes/{quote_id}/status")
async def get_quote_status(
    quote_id: str,
    principal: Principal = Depends(require_principal("bank:read")),
) -> dict:
    """Check if a quote is expired.  Returns ``{"expired": true/false}``."""
    from datetime import UTC, datetime

    from shared.timeutil import from_iso

    store = get_bank_store()
    quote = store.fetch_quote(quote_id)
    if quote is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="quote not found")
    expires = from_iso(quote["expires_at"])
    now = datetime.now(tz=UTC)
    return {"quote_id": quote_id, "expired": now >= expires, "expires_at": quote["expires_at"]}


# ── Transactions ───────────────────────────────────────────────────


@router.get("/transactions", response_model=list[TransactionResponse])
async def list_transactions(
    principal: Principal = Depends(require_principal("bank:read")),
    limit: int = Query(default=MAX_LIST_SIZE, ge=1, le=MAX_LIST_SIZE),
) -> list[dict]:
    store = get_bank_store()
    return store.get_transactions(principal.user_id, limit=limit)

"""Tests for ledger schema, init_db, seed idempotency, and money round-trip."""

from __future__ import annotations

import sqlite3
import tempfile
from pathlib import Path

import pytest

from ledger.schema import SCHEMA_VERSION, cents_to_money, connect, init_db, money_to_cents
from ledger.seed import seed_db
from shared.money import Money


@pytest.fixture()
def tmp_db_path() -> str:
    """Return a temp DB path that is cleaned up after the test."""
    with tempfile.NamedTemporaryFile(suffix=".db", delete=False) as f:
        path = f.name
    Path(path).unlink(missing_ok=True)
    yield path
    Path(path).unlink(missing_ok=True)


@pytest.fixture()
def seeded_conn(tmp_db_path: str) -> sqlite3.Connection:
    """Return a connection to a freshly seeded DB."""
    conn = connect(tmp_db_path)
    init_db(conn)
    seed_db(conn)
    yield conn
    conn.close()


class TestInitDb:
    def test_init_creates_all_tables(self, tmp_db_path: str) -> None:
        conn = connect(tmp_db_path)
        init_db(conn)
        rows = conn.execute(
            "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name"
        ).fetchall()
        table_names = {r["name"] for r in rows}
        expected = {
            "users", "kyc", "accounts", "account_holders",
            "payees", "payee_aliases", "billers", "saved_billers",
            "cards", "holdings", "equity_quotes", "mandates",
            "transactions", "receipts", "schema_meta",
        }
        assert expected.issubset(table_names)

    def test_init_is_idempotent(self, tmp_db_path: str) -> None:
        conn = connect(tmp_db_path)
        init_db(conn)
        init_db(conn)
        # Still works
        rows = conn.execute("SELECT COUNT(*) FROM users").fetchone()
        assert rows[0] == 0
        conn.close()

    def test_schema_version_recorded(self, tmp_db_path: str) -> None:
        conn = connect(tmp_db_path)
        init_db(conn)
        row = conn.execute("SELECT value FROM schema_meta WHERE key='version'").fetchone()
        assert int(row["value"]) == SCHEMA_VERSION
        conn.close()


class TestSeedIdempotency:
    def test_seed_twice_identical(self, tmp_db_path: str) -> None:
        conn = connect(tmp_db_path)
        init_db(conn)
        seed_db(conn)

        # Snapshot row counts and balances
        tables = [
            "users", "kyc", "accounts", "account_holders",
            "payees", "payee_aliases", "billers", "saved_billers",
            "cards", "holdings", "equity_quotes", "mandates",
        ]
        counts_1 = {t: conn.execute(f"SELECT COUNT(*) FROM {t}").fetchone()[0] for t in tables}
        balances_1 = {
            r["account_id"]: r["balance_cents"]
            for r in conn.execute("SELECT account_id, balance_cents FROM accounts").fetchall()
        }

        seed_db(conn)

        counts_2 = {t: conn.execute(f"SELECT COUNT(*) FROM {t}").fetchone()[0] for t in tables}
        balances_2 = {
            r["account_id"]: r["balance_cents"]
            for r in conn.execute("SELECT account_id, balance_cents FROM accounts").fetchall()
        }

        assert counts_1 == counts_2
        assert balances_1 == balances_2
        conn.close()

    def test_seed_users(self, seeded_conn: sqlite3.Connection) -> None:
        rows = seeded_conn.execute("SELECT user_id FROM users").fetchall()
        ids = {r["user_id"] for r in rows}
        assert ids == {"user-matthew", "user-ana"}

    def test_seed_matthew_accounts(self, seeded_conn: sqlite3.Connection) -> None:
        from ledger.schema import cents_to_money

        rows = seeded_conn.execute(
            "SELECT account_id, balance_cents FROM accounts WHERE account_id LIKE 'acct-matthew%'"
        ).fetchall()
        balances = {r["account_id"]: cents_to_money(r["balance_cents"]) for r in rows}
        assert balances["acct-matthew-savings"].to_str() == "12000.00"
        assert balances["acct-matthew-current"].to_str() == "3500.00"

    def test_seed_joint_account(self, seeded_conn: sqlite3.Connection) -> None:
        # Joint account should be held by both users
        holders = seeded_conn.execute(
            "SELECT user_id, role FROM account_holders WHERE account_id='acct-joint-01'"
        ).fetchall()
        holder_map = {r["user_id"]: r["role"] for r in holders}
        assert holder_map == {"user-matthew": "owner", "user-ana": "joint"}

        row = seeded_conn.execute(
            "SELECT balance_cents FROM accounts WHERE account_id='acct-joint-01'"
        ).fetchone()
        assert cents_to_money(row["balance_cents"]).to_str() == "2000.00"

    def test_seed_card_outstanding(self, seeded_conn: sqlite3.Connection) -> None:
        row = seeded_conn.execute(
            "SELECT outstanding_cents FROM cards WHERE card_id='card-matthew-01'"
        ).fetchone()
        assert cents_to_money(row["outstanding_cents"]).to_str() == "642.30"

    def test_seed_kyc(self, seeded_conn: sqlite3.Connection) -> None:
        mat = seeded_conn.execute(
            "SELECT status, tier, expires_at FROM kyc WHERE user_id='user-matthew'"
        ).fetchone()
        assert mat["status"] == "verified"
        assert mat["tier"] == 2
        assert mat["expires_at"].startswith("2027-12-31")

        ana = seeded_conn.execute(
            "SELECT status, tier FROM kyc WHERE user_id='user-ana'"
        ).fetchone()
        assert ana["status"] == "verified"
        assert ana["tier"] == 1

    def test_seed_mandate(self, seeded_conn: sqlite3.Connection) -> None:
        row = seeded_conn.execute(
            "SELECT version, status, per_leg_cents, daily_cents, allowed_actions "
            "FROM mandates WHERE user_id='user-matthew'"
        ).fetchone()
        assert row["version"] == 1
        assert row["status"] == "active"
        assert cents_to_money(row["per_leg_cents"]).to_str() == "1000.00"
        assert cents_to_money(row["daily_cents"]).to_str() == "3000.00"
        assert "transfer" in row["allowed_actions"]
        assert "buy_equity" in row["allowed_actions"]

    def test_seed_sanctioned_payee(self, seeded_conn: sqlite3.Connection) -> None:
        row = seeded_conn.execute(
            "SELECT display_name, sanctioned FROM payees WHERE payee_id='payee-northwind'"
        ).fetchone()
        assert row["display_name"] == "Northwind Trading"
        assert row["sanctioned"] == 1

    def test_seed_equity_quotes(self, seeded_conn: sqlite3.Connection) -> None:
        rows = seeded_conn.execute(
            "SELECT symbol, unit_price_cents, quoted_at, expires_at FROM equity_quotes"
        ).fetchall()
        symbols = {r["symbol"] for r in rows}
        assert symbols == {"D05", "O39", "U11", "Z74"}

        for r in rows:
            price = cents_to_money(r["unit_price_cents"])
            assert price.to_str() in {"38.50", "9.55", "28.30", "12.90"}
            # Quote expires 5 minutes after quoted_at
            quoted = r["quoted_at"]
            expires = r["expires_at"]
            assert quoted.startswith("2026-10-10T00:00:00")
            assert expires.startswith("2026-10-10T00:05:00")


class TestMoneyRoundTrip:
    """Money round-trips exactly through INTEGER cents."""

    @pytest.mark.parametrize(
        "money_str",
        ["0.01", "642.30", "12000.00", "999999.99", "0.00", "100.00"],
    )
    def test_round_trip(self, money_str: str) -> None:
        m = Money(money_str)
        cents = money_to_cents(m)
        assert cents == int(Money(money_str).value * 100)
        back = cents_to_money(cents)
        assert back.to_str() == money_str

    def test_no_real_columns(self, tmp_db_path: str) -> None:
        """Assert money columns are INTEGER, never REAL, via PRAGMA table_info."""
        conn = connect(tmp_db_path)
        init_db(conn)

        # Check all money-bearing columns are INTEGER
        money_columns = {
            "accounts": ["balance_cents"],
            "cards": ["outstanding_cents"],
            "equity_quotes": ["unit_price_cents"],
            "mandates": ["per_leg_cents", "daily_cents"],
            "transactions": ["amount_cents"],
        }
        for table, cols in money_columns.items():
            info = conn.execute(f"PRAGMA table_info({table})").fetchall()
            col_types = {r["name"]: r["type"] for r in info}
            for col in cols:
                assert col_types[col] == "INTEGER", (
                    f"{table}.{col} should be INTEGER, got {col_types[col]}"
                )
        conn.close()

"""AST boundary tests for service isolation (invariant I1).

Extends the T-01 shared-purity test with checks that:
- ``agent/`` and ``validator/`` do not import ``gateway`` or ``ledger``.
- ``shared/clients/`` has no write/execute methods (no POST other than
  quote issue).
- ``shared/`` does not import ``gateway`` or ``ledger``.
"""

from __future__ import annotations

import ast
from pathlib import Path

_REPO_ROOT = Path(__file__).resolve().parent.parent

_FORBIDDEN_FOR_AGENT_VALIDATOR = {"gateway", "ledger"}
_FORBIDDEN_FOR_SHARED = {"gateway", "ledger", "agent", "validator"}


def _extract_imports(tree: ast.AST) -> set[str]:
    """Extract all top-level module names from import statements."""
    modules: set[str] = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                modules.add(alias.name.split(".")[0])
        elif isinstance(node, ast.ImportFrom) and node.module:
            modules.add(node.module.split(".")[0])
    return modules


def _all_python_files(directory: str) -> list[Path]:
    root = _REPO_ROOT / directory
    if not root.exists():
        return []
    return sorted(root.rglob("*.py"))


class TestAgentValidatorIsolation:
    """agent/ and validator/ must not import gateway or ledger."""

    def test_agent_no_gateway_ledger(self) -> None:
        for f in _all_python_files("agent"):
            source = f.read_text(encoding="utf-8")
            tree = ast.parse(source, filename=str(f))
            imports = _extract_imports(tree)
            forbidden = imports & _FORBIDDEN_FOR_AGENT_VALIDATOR
            assert not forbidden, (
                f"agent/{f.relative_to(_REPO_ROOT / 'agent')} "
                f"imports forbidden modules: {forbidden}"
            )

    def test_validator_no_gateway_ledger(self) -> None:
        for f in _all_python_files("validator"):
            source = f.read_text(encoding="utf-8")
            tree = ast.parse(source, filename=str(f))
            imports = _extract_imports(tree)
            forbidden = imports & _FORBIDDEN_FOR_AGENT_VALIDATOR
            assert not forbidden, (
                f"validator/{f.relative_to(_REPO_ROOT / 'validator')} "
                f"imports forbidden modules: {forbidden}"
            )


class TestSharedExtendedPurity:
    """shared/ must not import gateway, ledger, agent or validator."""

    def test_no_forbidden_imports(self) -> None:
        for f in _all_python_files("shared"):
            source = f.read_text(encoding="utf-8")
            tree = ast.parse(source, filename=str(f))
            imports = _extract_imports(tree)
            forbidden = imports & _FORBIDDEN_FOR_SHARED
            assert not forbidden, (
                f"shared/{f.relative_to(_REPO_ROOT / 'shared')} "
                f"imports forbidden modules: {forbidden}"
            )


class TestSharedClientsNoWrite:
    """shared/clients/ must not contain write/execute methods.

    The only POST is quote issue (``issue_quote``), which creates a
    new immutable quote row.  No execute, no transfer, no payment
    methods.
    """

    def _bank_read_source(self) -> str:
        path = _REPO_ROOT / "shared" / "clients" / "bank_read.py"
        return path.read_text(encoding="utf-8")

    def test_no_execute_methods(self) -> None:
        """No method names suggesting execution or payment."""
        source = self._bank_read_source()
        tree = ast.parse(source)
        forbidden_names = {
            "execute", "execute_bundle", "update_mandate",
            "approve", "submit_approval", "transfer",
            "pay_bill", "pay_card", "buy_equity",
            "commit", "dispatch", "sign",
        }
        for node in ast.walk(tree):
            if isinstance(node, ast.FunctionDef):
                assert node.name not in forbidden_names, (
                    f"shared/clients/bank_read.py defines forbidden method: {node.name}"
                )
                # Also check async functions
            if isinstance(node, ast.AsyncFunctionDef):
                assert node.name not in forbidden_names, (
                    f"shared/clients/bank_read.py defines forbidden async method: {node.name}"
                )

    def test_only_post_is_issue_quote(self) -> None:
        """The only POST call in bank_read.py is for quote issue."""
        source = self._bank_read_source()
        tree = ast.parse(source)

        # Find all method calls that are POST requests
        post_methods = []
        for node in ast.walk(tree):
            if isinstance(node, ast.Call):
                func = node.func
                # Match httpx.post(...)
                if (
                    isinstance(func, ast.Attribute)
                    and isinstance(func.value, ast.Name)
                    and func.value.id == "httpx"
                    and func.attr == "post"
                ):
                    # Find which method this post call is inside
                    post_methods.append(func.attr)

        # All POST calls should be inside issue_quote
        # (we verify by checking that issue_quote exists and contains a POST)
        assert "post" in post_methods
        # No DELETE, PUT, PATCH
        for node in ast.walk(tree):
            if isinstance(node, ast.Call):
                func = node.func
                if (
                    isinstance(func, ast.Attribute)
                    and isinstance(func.value, ast.Name)
                    and func.value.id == "httpx"
                    and func.attr in ("delete", "put", "patch")
                ):
                    pytest.fail(
                        f"shared/clients/bank_read.py makes a {func.attr} request"
                    )
